<div class="gig-card" x-data="{}" dir="{{ config()->get('direction') }}">    <div class="bg-white dark:bg-zinc-800 rounded-md shadow-sm ring-1 ring-gray-200 dark:ring-zinc-800">        {{-- Preview --}}        <a href="{{ url('project/' . $pid . '/' . $slug) }}"           class="flex items-center justify-center overflow-hidden w-full h-52 bg-gray-100 dark:bg-zinc-700">            <img class="object-cover max-h-52 lazy h-52 w-full rounded-t-lg" src="{{ $thumbnail }}"                 data-src="{{ $thumbnail }}" alt="{{ $title }}">        </a>        {{-- Gig content --}}        <div class="px-4 pb-2 mt-4">            {{-- Title --}}            <a href="{{ url('project/' . $pid . '/' . $slug) }}"               class="gig-card-title font-semibold text-gray-800 dark:text-gray-100 hover:text-primary-600 dark:hover:text-white mb-4 !overflow-hidden">                {{ htmlspecialchars_decode($title) }}            </a>            {{-- Rating --}}            {{-- Reviews --}}            {{--                <div class="ltr:ml-2 rtl:mr-2 text-[13px] font-normal text-gray-400">--}}            <div class="flex items-center justify-center">                {{-- Bids --}}                <div class="flex items-center">                    <svg class="w-5 h-5 text-gray-400 ltr:mr-2 rtl:ml-2" stroke="currentColor"                         fill="currentColor"                         stroke-width="0" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">                        <path d="M11.707 2.293A.997.997 0 0 0 11 2H6a.997.997 0 0 0-.707.293l-3 3A.996.996 0 0 0 2 6v5c0 .266.105.52.293.707l10 10a.997.997 0 0 0 1.414 0l8-8a.999.999 0 0 0 0-1.414l-10-10zM13 19.586l-9-9V6.414L6.414 4h4.172l9 9L13 19.586z"></path>                        <circle cx="8.353" cy="8.353" r="1.647"></circle>                    </svg>                    <span class="text-sm text-gray-400 dark:text-gray-300 whitespace-nowrap">{{ $total_bids }} {{ strtolower(__('messages.t_bids')) }}</span>                </div>                {{-- Created at --}}                <div class="flex items-center ltr:ml-4 ltr:pl-4 ltr:border-l rtl:mr-4 rtl:pr-4 rtl:border-r border-gray-300 dark:border-zinc-600">                    <svg class="w-5 h-5 text-gray-400 ltr:mr-2 rtl:ml-2" stroke="currentColor"                         fill="currentColor"                         stroke-width="0" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">                        <path d="M12 2C6.486 2 2 6.486 2 12s4.486 10 10 10 10-4.486 10-10S17.514 2 12 2zm0 18c-4.411 0-8-3.589-8-8s3.589-8 8-8 8 3.589 8 8-3.589 8-8 8z"></path>                        <path d="M13 7h-2v5.414l3.293 3.293 1.414-1.414L13 11.586z"></path>                    </svg>                    <span class="text-sm text-gray-400 dark:text-gray-300 whitespace-nowrap">{{ $created_at }}</span>                </div>            </div>            {{--                </div>--}}        </div>        {{-- Gig footer --}}        <div class="px-3 py-3 bg-[#fdfdfd] dark:bg-zinc-800 border-t border-gray-50 dark:border-zinc-700 text-right sm:px-4 rounded-b-md flex justify-between">            {{-- Price --}}            <div class="gig-card-price">                <small class="text-body-3 dark:!text-zinc-200">{{ __('messages.t_starting_at') }}</small>                <span class=" ltr:text-right rtl:text-left dark:!text-white">{{ $budget_min . ' / ' . $budget_max }}</span>            </div>        </div>    </div></div>